import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, toJob, jobSelect } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
type FieldError = { field: string; message: string };

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}
function fail(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  send(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}
function invalid(res: ServerResponse, fields: FieldError[]): void {
  fail(res, 400, 'invalid_request', 'Request validation failed.', fields.length ? fields : [{ field: 'body', message: 'Invalid request.' }]);
}
async function readBody(req: IncomingMessage): Promise<string> {
  const chunks: Buffer[] = [];
  let length = 0;
  for await (const chunk of req) {
    const buf = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
    length += buf.length;
    if (length > 1_000_000) throw new Error('body too large');
    chunks.push(buf);
  }
  return Buffer.concat(chunks).toString('utf8');
}

async function handlePost(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const fields: FieldError[] = [];
  const contentType = req.headers['content-type'];
  if (!contentType || !/^application\/json(?:\s*;|\s*$)/i.test(contentType)) {
    fields.push({ field: 'body', message: 'Content-Type must be application/json.' });
  }
  const keyHeader = req.headers['idempotency-key'];
  const key = Array.isArray(keyHeader) ? keyHeader[0] : keyHeader;
  if (key !== undefined && !/^[A-Za-z0-9_-]{1,128}$/.test(key)) {
    fields.push({ field: 'Idempotency-Key', message: 'Must contain 1–128 letters, numbers, underscores, or hyphens.' });
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(await readBody(req));
  } catch {
    fields.push({ field: 'body', message: 'Body must contain valid JSON.' });
    invalid(res, fields);
    return;
  }
  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    fields.push({ field: 'body', message: 'Body must be a JSON object.' });
  } else {
    const body = parsed as Record<string, unknown>;
    for (const name of Object.keys(body)) if (!['input', 'steps', 'failAttempts'].includes(name)) fields.push({ field: name, message: 'Unknown field.' });
    if (!Object.hasOwn(body, 'input')) fields.push({ field: 'input', message: 'Required.' });
    else if (typeof body.input !== 'string') fields.push({ field: 'input', message: 'Must be a string.' });
    else if (body.input.length < 1 || body.input.length > 1000 || body.input.trim().length === 0) fields.push({ field: 'input', message: 'Must be 1–1000 characters and not only whitespace.' });
    if (Object.hasOwn(body, 'steps') && (!Number.isInteger(body.steps) || (body.steps as number) < 1 || (body.steps as number) > 20)) fields.push({ field: 'steps', message: 'Must be an integer from 1 to 20.' });
    if (Object.hasOwn(body, 'failAttempts') && (!Number.isInteger(body.failAttempts) || (body.failAttempts as number) < 0 || (body.failAttempts as number) > 5)) fields.push({ field: 'failAttempts', message: 'Must be an integer from 0 to 5.' });
  }
  if (fields.length) { invalid(res, fields); return; }

  const body = parsed as { input: string; steps?: number; failAttempts?: number };
  const payload = { input: body.input, steps: body.steps ?? 5, failAttempts: body.failAttempts ?? 0 };
  const payloadText = JSON.stringify(payload);
  if (key !== undefined) {
    const existing = db.prepare(`${jobSelect} WHERE idempotency_key = ?`).get(key) as Record<string, unknown> | undefined;
    if (existing) {
      const raw = db.prepare('SELECT payload FROM jobs WHERE idempotency_key = ?').get(key!) as { payload: string };
      if (raw.payload !== payloadText) { fail(res, 409, 'idempotency_conflict', 'Idempotency-Key was already used with a different payload.'); return; }
      send(res, 200, toJob(existing as never));
      return;
    }
  }
  const id = randomUUID();
  const now = new Date().toISOString();
  try {
    db.exec('BEGIN IMMEDIATE');
    const again = key === undefined ? undefined : db.prepare(`${jobSelect} WHERE idempotency_key = ?`).get(key) as Record<string, unknown> | undefined;
    if (again) {
      const raw = db.prepare('SELECT payload FROM jobs WHERE idempotency_key = ?').get(key!) as { payload: string };
      db.exec('COMMIT');
      if (raw.payload !== payloadText) { fail(res, 409, 'idempotency_conflict', 'Idempotency-Key was already used with a different payload.'); return; }
      send(res, 200, toJob(again as never));
      return;
    }
    db.prepare(`INSERT INTO jobs (id,status,input,steps,fail_attempts,attempts,completed,result,error,created_at,updated_at,available_at,idempotency_key,payload)
      VALUES (?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, ?, ?, 0, ?, ?)`).run(id, payload.input, payload.steps, payload.failAttempts, now, now, key ?? null, payloadText);
    db.exec('COMMIT');
  } catch (error) {
    try { db.exec('ROLLBACK'); } catch { /* transaction may already be closed */ }
    throw error;
  }
  const row = db.prepare(`${jobSelect} WHERE id = ?`).get(id) as never;
  send(res, 201, toJob(row));
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  void (async () => {
    const { pathname } = new URL(req.url ?? '/', 'http://localhost');
    if (pathname === '/' && req.method === 'GET') {
      res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' }); res.end(uiHtml); return;
    }
    if (pathname === '/') { fail(res, 405, 'method_not_allowed', 'Method not allowed.'); return; }
    if (pathname === '/health') {
      if (req.method !== 'GET') { fail(res, 405, 'method_not_allowed', 'Method not allowed.'); return; }
      const beat = db.prepare('SELECT seen_at FROM worker_heartbeat WHERE id = 1').get() as { seen_at: number } | undefined;
      send(res, 200, { status: 'ok', worker: beat && Date.now() - beat.seen_at < 3000 ? 'up' : 'down' }); return;
    }
    if (pathname === '/api/jobs') {
      if (req.method === 'POST') { await handlePost(req, res); return; }
      if (req.method === 'GET') {
        const rows = db.prepare(`${jobSelect} ORDER BY created_at DESC, rowid DESC`).all() as never[];
        send(res, 200, { jobs: rows.map(toJob) }); return;
      }
      fail(res, 405, 'method_not_allowed', 'Method not allowed.'); return;
    }
    const match = pathname.match(/^\/api\/jobs\/([^/]+)$/);
    if (match) {
      if (req.method !== 'GET') { fail(res, 405, 'method_not_allowed', 'Method not allowed.'); return; }
      let id: string;
      try { id = decodeURIComponent(match[1]!); } catch { fail(res, 404, 'not_found', 'Job not found.'); return; }
      const row = db.prepare(`${jobSelect} WHERE id = ?`).get(id) as never;
      if (!row) { fail(res, 404, 'not_found', 'Job not found.'); return; }
      send(res, 200, toJob(row)); return;
    }
    fail(res, 404, 'not_found', 'Route not found.');
  })().catch((error: unknown) => {
    console.error(error);
    if (!res.headersSent) fail(res, 500, 'internal_error', 'Internal server error.');
    else res.destroy();
  });
});
server.listen(port, '127.0.0.1', () => console.log(`server listening on ${port}`));
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => server.close(() => { db.close(); process.exit(0); }));

