2	import { openDatabase } from './db.ts';
3	
4	const db = openDatabase();
5	let stopping = false;
6	for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => { stopping = true; });
7	
8	// A running row belongs to a worker that no longer exists; its next pickup is a new attempt.
9	db.prepare(`UPDATE jobs SET status='queued', completed=0, available_at=0, updated_at=? WHERE status='running'`).run(new Date().toISOString());
10	const heartbeat = () => db.prepare(`INSERT INTO worker_heartbeat (id,seen_at) VALUES (1,?) ON CONFLICT(id) DO UPDATE SET seen_at=excluded.seen_at`).run(Date.now());
11	heartbeat();
12	const pulse = setInterval(() => { try { heartbeat(); } catch (error) { console.error(error); } }, 500);
13	console.log('worker started');
14	
15	function claim(): { id: string; input: string; steps: number; fail_attempts: number; attempts: number } | undefined {
16	  db.exec('BEGIN IMMEDIATE');
17	  try {
18	    const row = db.prepare(`SELECT id,input,steps,fail_attempts,attempts FROM jobs
19	      WHERE status='queued' AND available_at <= ? ORDER BY created_at ASC, rowid ASC LIMIT 1`).get(Date.now()) as
20	      { id: string; input: string; steps: number; fail_attempts: number; attempts: number } | undefined;
21	    if (!row) { db.exec('COMMIT'); return undefined; }
22	    const attempts = row.attempts + 1;
23	    db.prepare(`UPDATE jobs SET status='running',attempts=?,completed=0,result=NULL,error=NULL,updated_at=? WHERE id=?`)
24	      .run(attempts, new Date().toISOString(), row.id);
25	    db.exec('COMMIT');
26	    return { ...row, attempts };
27	  } catch (error) { try { db.exec('ROLLBACK'); } catch {} throw error; }
28	}
29	
30	async function processJob(job: NonNullable<ReturnType<typeof claim>>): Promise<void> {
31	  if (job.attempts <= job.fail_attempts) {
32	    if (job.attempts >= 3) {
33	      db.prepare(`UPDATE jobs SET status='failed',completed=0,result=NULL,error='transient failure',updated_at=? WHERE id=? AND status='running'`)
34	        .run(new Date().toISOString(), job.id);
35	    } else {
36	      db.prepare(`UPDATE jobs SET status='queued',completed=0,result=NULL,error=NULL,available_at=?,updated_at=? WHERE id=? AND status='running'`)
37	        .run(Date.now() + 500, new Date().toISOString(), job.id);
38	    }
39	    return;
40	  }
41	  for (let completed = 1; completed <= job.steps; completed++) {
42	    await sleep(100);
43	    db.prepare(`UPDATE jobs SET completed=?,updated_at=? WHERE id=? AND status='running'`)
44	      .run(completed, new Date().toISOString(), job.id);
45	  }
46	  db.prepare(`UPDATE jobs SET status='completed',completed=steps,result=?,error=NULL,updated_at=? WHERE id=? AND status='running'`)
47	    .run(JSON.stringify({ output: job.input.toUpperCase() }), new Date().toISOString(), job.id);
48	}
49	
50	try {
51	  while (!stopping) {
52	    const job = claim();
53	    if (job) await processJob(job);
54	    else await sleep(100);
55	  }
56	} finally {
57	  clearInterval(pulse);
58	  try { db.prepare('DELETE FROM worker_heartbeat WHERE id=1').run(); } catch { /* database may be closing */ }
59	  db.close();
60	}
