import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => { stopping = true; });

// A running row belongs to a worker that no longer exists; its next pickup is a new attempt.
db.prepare(`UPDATE jobs SET status='queued', completed=0, available_at=0, updated_at=? WHERE status='running'`).run(new Date().toISOString());
const heartbeat = () => db.prepare(`INSERT INTO worker_heartbeat (id,seen_at) VALUES (1,?) ON CONFLICT(id) DO UPDATE SET seen_at=excluded.seen_at`).run(Date.now());
heartbeat();
const pulse = setInterval(() => { try { heartbeat(); } catch (error) { console.error(error); } }, 500);
console.log('worker started');

function claim(): { id: string; input: string; steps: number; fail_attempts: number; attempts: number } | undefined {
  db.exec('BEGIN IMMEDIATE');
  try {
    const row = db.prepare(`SELECT id,input,steps,fail_attempts,attempts FROM jobs
      WHERE status='queued' AND available_at <= ? ORDER BY created_at ASC, rowid ASC LIMIT 1`).get(Date.now()) as
      { id: string; input: string; steps: number; fail_attempts: number; attempts: number } | undefined;
    if (!row) { db.exec('COMMIT'); return undefined; }
    const attempts = row.attempts + 1;
    db.prepare(`UPDATE jobs SET status='running',attempts=?,completed=0,result=NULL,error=NULL,updated_at=? WHERE id=?`)
      .run(attempts, new Date().toISOString(), row.id);
    db.exec('COMMIT');
    return { ...row, attempts };
  } catch (error) { try { db.exec('ROLLBACK'); } catch {} throw error; }
}

async function processJob(job: NonNullable<ReturnType<typeof claim>>): Promise<void> {
  if (job.attempts <= job.fail_attempts) {
    if (job.attempts >= 3) {
      db.prepare(`UPDATE jobs SET status='failed',completed=0,result=NULL,error='transient failure',updated_at=? WHERE id=? AND status='running'`)
        .run(new Date().toISOString(), job.id);
    } else {
      db.prepare(`UPDATE jobs SET status='queued',completed=0,result=NULL,error=NULL,available_at=?,updated_at=? WHERE id=? AND status='running'`)
        .run(Date.now() + 500, new Date().toISOString(), job.id);
    }
    return;
  }
  for (let completed = 1; completed <= job.steps; completed++) {
    await sleep(100);
    db.prepare(`UPDATE jobs SET completed=?,updated_at=? WHERE id=? AND status='running'`)
      .run(completed, new Date().toISOString(), job.id);
  }
  db.prepare(`UPDATE jobs SET status='completed',completed=steps,result=?,error=NULL,updated_at=? WHERE id=? AND status='running'`)
    .run(JSON.stringify({ output: job.input.toUpperCase() }), new Date().toISOString(), job.id);
}

try {
  while (!stopping) {
    const job = claim();
    if (job) await processJob(job);
    else await sleep(100);
  }
} finally {
  clearInterval(pulse);
  try { db.prepare('DELETE FROM worker_heartbeat WHERE id=1').run(); } catch { /* database may be closing */ }
  db.close();
}

