4	  <meta charset="utf-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1">
6	  <title>Job tracker</title>
7	  <style>
8	    body { font: 16px system-ui, sans-serif; max-width: 760px; margin: 2rem auto; padding: 0 1rem; color: #20232a; }
9	    form { display: grid; gap: .75rem; max-width: 34rem; padding: 1rem; border: 1px solid #ccd1d8; border-radius: 8px; }
10	    label { display: grid; gap: .25rem; } input, button { font: inherit; padding: .5rem; }
11	    [role=alert] { color: #a21b1b; min-height: 1.4em; }
12	    #job-list { list-style: none; padding: 0; } [data-testid=job-item] { border: 1px solid #ccd1d8; border-radius: 8px; padding: .8rem; margin: .65rem 0; }
13	    .meta { color: #515966; display: flex; gap: 1rem; flex-wrap: wrap; }
14	    .output { overflow-wrap: anywhere; white-space: pre-wrap; }
15	  </style>
16	</head>
17	<body>
18	  <h1>Job tracker</h1>
19	  <form data-testid="job-form">
20	    <label>Input <input data-testid="job-input" name="input" type="text" maxlength="1000" required></label>
21	    <label>Steps <input data-testid="job-steps" name="steps" type="number" min="1" max="20" step="1" value="5"></label>
22	    <label>Fail attempts <input data-testid="job-fail-attempts" name="failAttempts" type="number" min="0" max="5" step="1" value="0"></label>
23	    <button data-testid="job-submit" type="submit">Submit job</button>
24	    <div data-testid="form-error" role="alert"></div>
25	  </form>
26	  <h2>Jobs</h2>
27	  <ul data-testid="job-list"></ul>
28	  <script>
29	    const form = document.querySelector('[data-testid="job-form"]');
30	    const errorRegion = document.querySelector('[data-testid="form-error"]');
31	    const list = document.querySelector('[data-testid="job-list"]');
32	    function renderError(data) {
33	      const error = data && data.error;
34	      if (!error) { errorRegion.textContent = 'The server rejected the submission.'; return; }
35	      const fields = (error.fields || []).map(item => `${item.field}: ${item.message}`);
36	      errorRegion.textContent = [error.message, ...fields].join(' ');
37	    }
38	    function addText(parent, tag, testid, text, className) {
39	      const el = document.createElement(tag);
40	      el.dataset.testid = testid;
41	      if (className) el.className = className;
42	      el.textContent = text;
43	      parent.append(el);
44	      return el;
45	    }
46	    function render(jobs) {
47	      list.replaceChildren();
48	      for (const job of jobs) {
49	        const item = document.createElement('li');
50	        item.dataset.testid = 'job-item';
51	        item.dataset.jobId = job.id;
52	        const heading = document.createElement('strong');
53	        heading.textContent = job.input;
54	        item.append(heading);
55	        const meta = document.createElement('div'); meta.className = 'meta';
56	        addText(meta, 'span', 'job-status', job.status);
57	        addText(meta, 'span', 'job-progress', `${job.progress.completed}/${job.progress.total}`);
58	        item.append(meta);
59	        const output = job.status === 'completed' ? job.result.output : job.status === 'failed' ? job.error : '';
60	        addText(item, 'div', 'job-result', output || '', 'output');
61	        list.append(item);
62	      }
63	    }
64	    async function refresh() {
65	      try {
66	        const response = await fetch('/api/jobs');
67	        if (response.ok) render((await response.json()).jobs);
68	      } catch (_) { /* the next poll will retry */ }
69	    }
70	    form.addEventListener('submit', async event => {
71	      event.preventDefault();
72	      errorRegion.textContent = '';
73	      const input = form.querySelector('[name=input]').value;
74	      const steps = form.querySelector('[name=steps]').value;
75	      const failAttempts = form.querySelector('[name=failAttempts]').value;
76	      const payload = { input, steps: steps === '' ? '' : Number(steps), failAttempts: failAttempts === '' ? '' : Number(failAttempts) };
77	      try {
78	        const response = await fetch('/api/jobs', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
79	        const data = await response.json();
80	        if (!response.ok) renderError(data);
81	        else { errorRegion.textContent = ''; await refresh(); }
82	      } catch (_) { errorRegion.textContent = 'Unable to submit job. Please try again.'; }
83	    });
84	    refresh();
85	    setInterval(refresh, 750);
86	  </script>
87	</body>
88	</html>
